//! The `p1:module/credential-method` world's bindings, generated by `wit-bindgen` into
//! [`generated`](self::generated) for a credential-method component (ADR-0212).
//!
//! The same separate-crate pattern as `p1-bindings-tool`: the `export!` macro `wit-bindgen`
//! writes needs `unsafe`, and every crate of this workspace forbids `unsafe_code` (the
//! workspace lint), so `generate!` runs in this crate and `pub_export_macro` exports the macro
//! a component crate calls.
#![forbid(unsafe_code)]

/// The generated bindings for the `credential-method` world of the WIT package in
/// [`modules/wit`].
///
/// [`modules/wit`]: ../../wit
pub mod generated {
    wit_bindgen::generate!({
        path: "../wit",
        world: "credential-method",
        pub_export_macro: true,
        default_bindings_module: "p1_bindings_credential_method::generated",
    });
}
